package murat.simv2.analysis;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Generates two files used by the runtime side:
 *
 * <ul>
 *   <li>{@code GeneratedSync.java} — copies every sliced field from the real
 *       {@link net.minecraft.client.network.ClientPlayerEntity} onto the mirror
 *       simulator. Primitive fields copy directly; a small set of value types
 *       (Vec3d / Vec3i / BlockPos / Box / EntityPose) round-trip through their
 *       mirror constructors. Everything else is left at the simulator default.</li>
 *   <li>{@code sim-v2.accesswidener} — opens up the visibility of every field
 *       the sync method touches, so {@code GeneratedSync} can read the real
 *       player without reflection.</li>
 * </ul>
 *
 * <p>This class is regenerated on every WALA run; it never inspects mirror
 * source files, only the field manifest from the slice.
 */
final class SyncCodeGenerator {
    private final Path outputDir;

    SyncCodeGenerator(Path outputDir) {
        this.outputDir = outputDir;
    }

    void generate(List<FieldResult> fields) throws IOException {
        List<FieldResult> syncable = new ArrayList<>();
        for (FieldResult f : fields) {
            if (AnalysisConfig.DO_NOT_SYNC_FIELDS.contains(f.fieldName())) continue;
            syncable.add(f);
        }
        writeSyncClass(syncable);
        writeAccessWidener(syncable);
    }

    private void writeSyncClass(List<FieldResult> fields) throws IOException {
        Path javaDir = outputDir.resolve("java/murat/simv2/simulation");
        Files.createDirectories(javaDir);

        StringBuilder sb = new StringBuilder();
        sb.append("package murat.simv2.simulation;\n\n");
        sb.append("import net.minecraft.client.network.ClientPlayerEntity;\n\n");
        sb.append("/** Generated by movement analysis. Do not edit. */\n");
        sb.append("public final class GeneratedSync {\n");
        sb.append("    private GeneratedSync() {\n");
        sb.append("    }\n\n");

        sb.append("    public static void sync(\n");
        sb.append("        ClientPlayerEntity real,\n");
        sb.append("        murat.simv2.simulation.mirror.net.minecraft.client.network.ClientPlayerEntity sim\n");
        sb.append("    ) {\n");
        String currentClass = null;
        for (FieldResult f : fields) {
            if (!f.declaringClass().equals(currentClass)) {
                if (currentClass != null) sb.append('\n');
                sb.append("        // ── ").append(f.declaringClass()).append(" ──\n");
                currentClass = f.declaringClass();
            }
            String line = renderFieldCopy(f);
            if (line != null) {
                sb.append("        ").append(line).append('\n');
            } else {
                sb.append("        // skip ").append(f.fieldName())
                    .append(" : ").append(f.typeDescriptor())
                    .append(" (no automatic converter; mirror keeps its default)\n");
            }
        }
        sb.append("    }\n");
        sb.append("}\n");

        Files.writeString(javaDir.resolve("GeneratedSync.java"), sb.toString());
        System.out.println("Generated GeneratedSync.java with " + fields.size() + " fields");
    }

    /**
     * Produces a single Java line copying {@code real.<field>} onto the
     * matching mirror field on {@code sim}. Returns null if there is no
     * supported converter for the descriptor.
     */
    private String renderFieldCopy(FieldResult f) {
        String name = f.fieldName();
        String desc = f.typeDescriptor();
        if (desc == null || desc.isEmpty()) return null;

        // Primitives.
        if (desc.length() == 1 && "ZBCSIJFD".indexOf(desc.charAt(0)) >= 0) {
            return "sim." + name + " = real." + name + ";";
        }
        // Reference: only emit for descriptors we have a converter for.
        String converter = converterCall(desc, "real." + name);
        if (converter == null) return null;
        return "sim." + name + " = " + converter + ";";
    }

    /**
     * Returns a Java expression that converts a real-MC value of descriptor
     * {@code desc} into its mirror counterpart, or null if the descriptor is
     * not a value type we know how to round-trip.
     */
    private String converterCall(String desc, String realExpr) {
        return switch (desc) {
            case "Lnet/minecraft/util/math/Vec3d;" -> realExpr + " == null ? null"
                + " : new murat.simv2.simulation.mirror.net.minecraft.util.math.Vec3d("
                + realExpr + ".x, " + realExpr + ".y, " + realExpr + ".z)";
            case "Lnet/minecraft/util/math/Vec3i;" -> realExpr + " == null ? null"
                + " : new murat.simv2.simulation.mirror.net.minecraft.util.math.Vec3i("
                + realExpr + ".getX(), " + realExpr + ".getY(), " + realExpr + ".getZ())";
            case "Lnet/minecraft/util/math/BlockPos;" -> realExpr + " == null ? null"
                + " : new murat.simv2.simulation.mirror.net.minecraft.util.math.BlockPos("
                + realExpr + ".getX(), " + realExpr + ".getY(), " + realExpr + ".getZ())";
            case "Lnet/minecraft/util/math/Box;" -> realExpr + " == null ? null"
                + " : new murat.simv2.simulation.mirror.net.minecraft.util.math.Box("
                + realExpr + ".minX, " + realExpr + ".minY, " + realExpr + ".minZ,"
                + realExpr + ".maxX, " + realExpr + ".maxY, " + realExpr + ".maxZ)";
            case "Lnet/minecraft/entity/EntityPose;" -> realExpr + " == null ? null"
                + " : murat.simv2.simulation.mirror.net.minecraft.entity.EntityPose.valueOf("
                + realExpr + ".name())";
            default -> null;
        };
    }

    private void writeAccessWidener(List<FieldResult> fields) throws IOException {
        StringBuilder sb = new StringBuilder();
        sb.append("accessWidener v2 named\n\n");
        sb.append("# Generated by movement analysis. Do not edit.\n");
        for (FieldResult f : fields) {
            sb.append(String.format(Locale.ROOT,
                "accessible field %s %s %s%n",
                f.declaringClass().replace('.', '/'),
                f.fieldName(),
                f.typeDescriptor()));
        }
        // tickMovement() is the entry the runtime calls each tick on the simulator.
        sb.append("accessible method net/minecraft/client/network/ClientPlayerEntity tickMovement ()V\n");

        String text = sb.toString();
        Path generatedAw = AnalysisArtifacts.accessWidenerPath(outputDir);
        Files.writeString(generatedAw, text);
        Path resourcesAw = AnalysisArtifacts.resourcesAccessWidenerPath(outputDir);
        if (Files.isDirectory(resourcesAw.getParent())) {
            Files.writeString(resourcesAw, text);
        }
        System.out.println("Generated sim-v2.accesswidener");
    }
}
